// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /api/v1/quoting/requests)
	ListQuoteRequests(ctx context.Context, request ListQuoteRequestsRequestObject) (ListQuoteRequestsResponseObject, error)

	// (POST /api/v1/quoting/requests)
	CreateQuoteRequest(ctx context.Context, request CreateQuoteRequestRequestObject) (CreateQuoteRequestResponseObject, error)

	// (GET /api/v1/quoting/requests/{requestId})
	GetQuoteRequest(ctx context.Context, request GetQuoteRequestRequestObject) (GetQuoteRequestResponseObject, error)

	// (POST /api/v1/quoting/requests/{requestId}/accept)
	AcceptQuoteOffer(ctx context.Context, request AcceptQuoteOfferRequestObject) (AcceptQuoteOfferResponseObject, error)

	// (POST /api/v1/quoting/requests/{requestId}/decline)
	DeclineQuoteRequest(ctx context.Context, request DeclineQuoteRequestRequestObject) (DeclineQuoteRequestResponseObject, error)

	// (POST /api/v1/quoting/requests/{requestId}/offers)
	AddQuoteOffer(ctx context.Context, request AddQuoteOfferRequestObject) (AddQuoteOfferResponseObject, error)

	// (GET /api/v1/quoting/settings)
	GetQuotingSettings(ctx context.Context, request GetQuotingSettingsRequestObject) (GetQuotingSettingsResponseObject, error)

	// (PUT /api/v1/quoting/settings)
	SetQuotingSettings(ctx context.Context, request SetQuotingSettingsRequestObject) (SetQuotingSettingsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListQuoteRequests operation middleware
func (sh *strictHandler) ListQuoteRequests(w http.ResponseWriter, r *http.Request, params ListQuoteRequestsParams) {
	var request ListQuoteRequestsRequestObject

	request.Params = params

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListQuoteRequests(ctx, request.(ListQuoteRequestsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListQuoteRequests")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListQuoteRequestsResponseObject); ok {
		if err := validResponse.VisitListQuoteRequestsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

// CreateQuoteRequest operation middleware
